-- Phase-1 schema repair batch generated by scripts/verify-schema.ts.
-- No data is changed. These policies make album membership accessible only
-- through albums owned by the authenticated Vaultly user.
-- DROP POLICY IF EXISTS first so a fresh 0001→0010 apply is re-runnable.
drop policy if exists album_backups_select_via_album on public.album_backups;
create policy album_backups_select_via_album
on public.album_backups
for select
to authenticated
using (
  album_id in (
    select id
    from public.albums
    where user_id = (
      select id
      from public.users
      where privy_user_id = (select auth.uid())::text
    )
  )
);

drop policy if exists album_backups_insert_via_album on public.album_backups;
create policy album_backups_insert_via_album
on public.album_backups
for insert
to authenticated
with check (
  album_id in (
    select id
    from public.albums
    where user_id = (
      select id
      from public.users
      where privy_user_id = (select auth.uid())::text
    )
  )
);

drop policy if exists album_backups_delete_via_album on public.album_backups;
create policy album_backups_delete_via_album
on public.album_backups
for delete
to authenticated
using (
  album_id in (
    select id
    from public.albums
    where user_id = (
      select id
      from public.users
      where privy_user_id = (select auth.uid())::text
    )
  )
);
